// #region Imports
import {
    RemoteProtocolError,
    remoteProtocolVersion,
    type IRemoteRouteDefinition,
} from '@pixel-brewery/remote-protocol';
import { RemoteRouteRegistry } from './RemoteRouteRegistry.js';
import type { IRemoteNativeRouteSourceOptions } from './interfaces/IRemoteNativeRouteSourceOptions.js';
import type { IRemoteNativeRouteSources } from './interfaces/IRemoteNativeRouteSources.js';
// #endregion

const header =
    '// Generated by @pixel-brewery/remote-core createRemoteNativeRouteSources. Do not edit.';
const nativeMaxRequestBytes = 67108864;
const identifier = /^[A-Za-z_][A-Za-z0-9_]{0,127}$/u;

/**
 * Emits one canonical route inventory as JSON, Kotlin and Swift source text.
 *
 * @remarks
 * The routes are validated and canonicalized through {@link RemoteRouteRegistry}
 * and sorted by path, method and identifier using code-unit order, so the output
 * is independent of input order. Kotlin and Swift construct the remote-capacitor
 * `RemoteNativeConfiguration.Route` values with an explicit `maxRequestBytes`;
 * the native SDKs accept at most 64 MiB. String literals escape quotes,
 * backslashes, control and line-separator characters, and Kotlin `$` templates.
 * Generation is pure: it writes no file and starts no runtime.
 *
 * @param routes - Complete product route set, typically from {@link createRemoteRoutesFromOpenApi}.
 * @param options - Application namespace, protocol version and native declaration names.
 * @returns Frozen JSON, Kotlin and Swift source strings, each ending with a newline.
 * @throws RemoteProtocolError with `invalid-request` for an empty or registry-inadmissible route set, a route
 * without an explicit request quota or above the native 64 MiB limit, an invalid application namespace,
 * protocol version or native identifier.
 *
 * @example
 * ```ts
 * const sources = createRemoteNativeRouteSources(routes, {
 *     appId: 'com.example.product',
 *     kotlin: { packageName: 'com.example.product.remote', objectName: 'ProductRemoteRoutes' },
 *     swift: { typeName: 'ProductRemoteRoutes' },
 * });
 * ```
 *
 * @public
 */
export function createRemoteNativeRouteSources(
    routes: readonly IRemoteRouteDefinition[],
    options: IRemoteNativeRouteSourceOptions,
): IRemoteNativeRouteSources {
    if (!/^[a-z][a-z0-9.-]{0,79}$/u.test(options.appId))
        invalid('The remote application namespace is invalid.');
    const protocolVersion = options.protocolVersion ?? remoteProtocolVersion;
    if (!Number.isSafeInteger(protocolVersion) || protocolVersion < 1)
        invalid('The remote protocol version is invalid.');
    const packageName = options.kotlin.packageName;
    if (packageName.length > 255 || !packageName.split('.').every((part) => identifier.test(part)))
        invalid('The Kotlin package name is invalid.');
    const objectName = name(options.kotlin.objectName, 'The Kotlin object name is invalid.');
    const typeName = name(options.swift.typeName, 'The Swift type name is invalid.');
    if (routes.length === 0) invalid('No remote routes were supplied.');
    const registry = new RemoteRouteRegistry(routes);
    const canonical = routes
        .map((route) => {
            const definition = registry.match(route.method, route.path);
            if (definition.id !== route.id) invalid('The remote route set is ambiguous.');
            const maxRequestBytes = definition.maxRequestBytes;
            if (maxRequestBytes === undefined || maxRequestBytes > nativeMaxRequestBytes)
                invalid('Remote routes must declare a native request quota of at most 64 MiB.');
            return {
                id: definition.id,
                method: definition.method,
                path: definition.path,
                kind: definition.kind,
                capabilities: [...definition.capabilities],
                retry: definition.retry,
                maxRequestBytes,
            };
        })
        .sort(
            (left, right) =>
                compare(left.path, right.path) ||
                compare(left.method, right.method) ||
                compare(left.id, right.id),
        );
    const kotlin = canonical.map(
        (route) =>
            `        RemoteNativeConfiguration.Route(id = ${literal(route.id, 'kotlin')}, method = ${literal(route.method, 'kotlin')}, path = ${literal(route.path, 'kotlin')}, kind = ${literal(route.kind, 'kotlin')}, capabilities = setOf(${route.capabilities.map((value) => literal(value, 'kotlin')).join(', ')}), maxRequestBytes = ${route.maxRequestBytes}L),`,
    );
    const swift = canonical.map(
        (route) =>
            `            try .init(id: ${literal(route.id, 'swift')}, method: ${literal(route.method, 'swift')}, path: ${literal(route.path, 'swift')}, kind: ${literal(route.kind, 'swift')}, capabilities: Set([${route.capabilities.map((value) => literal(value, 'swift')).join(', ')}]), maxRequestBytes: ${route.maxRequestBytes}),`,
    );
    return Object.freeze({
        json:
            JSON.stringify({ appId: options.appId, protocolVersion, routes: canonical }, null, 2) +
            '\n',
        kotlin: [
            header,
            `package ${packageName}`,
            '',
            '// #region Imports',
            'import de.pixelbrewery.remote.configuration.RemoteNativeConfiguration',
            '// #endregion',
            '',
            '/**',
            ' * Remote route admission generated from the application route set.',
            ' */',
            `internal object ${objectName} {`,
            '    /** Every admitted product route; private host administration is absent. */',
            '    val routes: List<RemoteNativeConfiguration.Route> = listOf(',
            ...kotlin,
            '    )',
            '}',
            '',
        ].join('\n'),
        swift: [
            header,
            '// #region Imports',
            'import RemoteCapacitor',
            '// #endregion',
            '',
            '/// Remote route admission generated from the application route set.',
            `internal enum ${typeName} {`,
            '    /// Validates every typed SDK route value without a second handwritten policy.',
            '    static func make() throws -> [RemoteNativeConfiguration.Route] {',
            '        [',
            ...swift,
            '        ]',
            '    }',
            '}',
            '',
        ].join('\n'),
    });
}

/**
 * Encodes one value as a double-quoted Kotlin or Swift string literal.
 *
 * @param value - Exact string to preserve.
 * @param language - Target language selecting the Unicode escape and template rules.
 * @returns A literal that evaluates to exactly the supplied value.
 *
 * @internal
 */
function literal(value: string, language: 'kotlin' | 'swift'): string {
    const slash = String.fromCharCode(92);
    return (
        '"' +
        Array.from(value, (character) => {
            if (character === '"' || character === slash) return slash + character;
            const point = character.codePointAt(0) ?? 0;
            if (point === 10) return slash + 'n';
            if (point === 13) return slash + 'r';
            if (point === 9) return slash + 't';
            if (point < 32 || point === 0x7f || point === 0x2028 || point === 0x2029)
                return (
                    slash +
                    (language === 'swift'
                        ? `u{${point.toString(16)}}`
                        : `u${point.toString(16).padStart(4, '0')}`)
                );
            return character === '$' && language === 'kotlin' ? slash + '$' : character;
        }).join('') +
        '"'
    );
}

/**
 * Validates one generated declaration identifier.
 *
 * @param value - Candidate identifier supplied by the application.
 * @param message - Fixed diagnostic for an invalid identifier.
 * @returns The unchanged identifier.
 * @throws RemoteProtocolError when the identifier is not a plain ASCII identifier.
 *
 * @internal
 */
function name(value: string, message: string): string {
    if (!identifier.test(value)) invalid(message);
    return value;
}

/**
 * Orders strings by UTF-16 code units, independent of the runtime locale.
 *
 * @param left - First compared value.
 * @param right - Second compared value.
 * @returns A negative, zero or positive ordinal comparison result.
 *
 * @internal
 */
function compare(left: string, right: string): number {
    return left < right ? -1 : left > right ? 1 : 0;
}

/**
 * Rejects invalid generation input without echoing the submitted values.
 *
 * @param message - Fixed safe diagnostic.
 * @throws RemoteProtocolError with `invalid-request`.
 *
 * @internal
 */
function invalid(message: string): never {
    throw new RemoteProtocolError('invalid-request', message);
}
